                if fp > now * 1.005 then q = now / fp end
            else
                q = now / math.max(b0, 1)
                if q > 1.0001 then q = nil end
            end
            if q and (not bq or q < bq) then best, bq = r, q end
        end
    end
    if not best then return end
    local ok, a = pcall(function() return G.R.RerollRobot:InvokeServer(best.Id, { Cost = 0, Fixed = fixed }) end)
    LOG("reroll", best.Id, ok, a)
    if ok and a then say(__T["Rerolled a robot"]) end
end
B.KIND = { Damage = 8, Speed = 7, Health = 6, Armor = 5, Crit = 4, Thorns = 3, Heal = 2, Carry = 1 }
function B.dScore(code)
    if type(code) ~= "string" or code == "" then return -1 end
    local k, r = code:match("^(%a+):(%d+)")
    return (tonumber(r) or 0) * 10 + (B.KIND[k] or 0)
end
function B.drones()
    local Dr = G.Dr
    local pd = G.pd()
    if not (Dr and pd.Drones and Dr.Hubs) or G.rebirths() < (tonumber(Dr.Unlock) or 1) then return end
    local fixed = lp:GetAttribute("RandomRestricted") ~= false
    local hub = "Overworld"
    local pend = gcall(Dr.PendingOf, pd, hub)
    if type(pend) == "string" and pend ~= "" then
        local slots = Dr.Hubs[hub].Slots or {}
        local target, ts
        for _, sl in ipairs(slots) do
            if gcall(Dr.SlotOpen, pd, sl) and gcall(Dr.Fits, pd, sl, pend, fixed) then
                local cur = pd.Drones.Slots and (pd.Drones.Slots[sl] or pd.Drones.Slots[tostring(sl)])
                local sc = B.dScore(cur)
                if sc < B.dScore(pend) and (not ts or sc < ts) then target, ts = sl, sc end
            end
        end
        local ok, a
        if target then
            ok, a = pcall(function() return G.R.KeepDrone:InvokeServer(target, pend) end)
            if ok and a then say(__T["Kept drone "] .. pend) end
        else
            ok, a = pcall(function() return G.R.DropDrone:InvokeServer(pend, hub) end)
        end
        LOG("drone", pend, target, ok, a)
        return
    end
    local cost = tonumber(gcall(Dr.Cost, pd, Workspace:GetServerTimeNow() - 2, hub)) or math.huge
    local budget = G.cash() * (tonumber(val("d_budget", 20)) or 20) / 100
    if cost == 0 or cost <= budget then
        local ok, a, b = pcall(function() return G.R.RollDrone:InvokeServer({ Cost = cost, Fixed = fixed, Hub = hub }) end)
        LOG("droll", cost, ok, a, b)
    end
end
function B.specOf(plan) local t = {} for i, sl in ipairs(B.SLOTS) do local k = plan[sl] t[i] = k and k:match("^(.-:%d+):") or "" end return table.concat(t, "|") end
function L.beats(key, sl)
    local robots = G.pd().Robots
    local idx = table.find(B.SLOTS, sl)
    if not (robots and robots.Built and idx) then return false end
    local weakest, wp
    for _, id in pairs(robots.Equipped or {}) do local r = robots.Built[id] if r then local p = B.pot(r.Spec, r.Traits) if not wp or p < wp then weakest, wp = r, p end end end
    if not weakest then return true end
    local parts = string.split(tostring(weakest.Spec), "|")
    local cur = parts[idx] and parts[idx] ~= "" and (parts[idx] .. ":" .. sl)
    local best = cur and B.partVal(cur, sl) or 0
    for k, n in pairs(robots.Parts or {}) do if (tonumber(n) or 0) > 0 and tostring(k):match(":%d+:(%a+)$") == sl then best = math.max(best, B.partVal(k, sl)) end end
    if B.partVal(key, sl) > best * 1.25 + 1 then return true end
    local p = B.plan(key)
    return p ~= nil and B.pot(B.specOf(p)) > wp * 1.1
end
